using NUnit.Framework;\nusing Microsoft.Playwright;\nusing System;\nusing System.Text.Json;\nusing System.Threading.Tasks;\nusing System.Collections.Generic;\nusing TestBase;\nusing Models;\n\nnamespace ApiTests\n{\n    public class PostDataTests : UiTestBase\n    {\n        [Test]\n        public async Task PostDataItem_ShouldReturnCreatedItem()\n        {\n            // Arrange\n            var newItem = new DataItem\n            {\n                Name = \"Test Item \" + Guid.NewGuid(),\n                Description = \"Optional description\"\n            };\n            var options = new APIRequestContextOptions\n            {\n                Headers = new Dictionary<string, string>\n                {\n                    { \"Content-Type\", \"application/json\" }\n                },\n                Data = JsonSerializer.Serialize(newItem, new JsonSerializerOptions\n                {\n                    PropertyNamingPolicy = JsonNamingPolicy.CamelCase\n                })\n            };\n\n            // Act\n            TestContext.WriteLine(\"📤 Request Payload:\\n\" + JsonSerializer.Serialize(newItem, new JsonSerializerOptions { WriteIndented = true }));\n            var response = await API.PostAsync(\"/api/data\", options);\n            var responseBody = (JsonElement)await response.JsonAsync();\n            TestContext.WriteLine(\"📥 Response Body:\\n\" + responseBody.ToString());\n\n            // Assert\n            Assert.IsTrue(responseBody.TryGetProperty(\"id\", out JsonElement idElement), \"Response does not contain 'id'\");\n            Assert.IsTrue(responseBody.TryGetProperty(\"name\", out JsonElement nameElement), \"Response does not contain 'name'\");\n            Assert.AreEqual(newItem.Name, nameElement.GetString(), \"The name of the created item does not match the request payload.\");\n        }\n    }\n}\n